-- Correção: os produtos de produção própria criados pelos seeds anteriores
-- (seed-bakery-products.sql e seed-bakery-products-batch2.sql) vincularam as
-- matérias-primas direto em `product_recipe_item` (produto -> matéria-prima),
-- que é o mecanismo de "matéria-prima avulsa" do cadastro de produto.
--
-- O jeito certo, usado pela tela de Receitas do projeto, é: cadastrar uma
-- `recipe` (receita reutilizável), os itens dela em `recipe_item`
-- (receita -> matéria-prima), e então ligar a receita ao produto final via
-- `product_recipe_link` (produto -> receita). É esse o caminho que
-- CreateProductUseCase usa pra somar `recipesCost` no cálculo de custo
-- (RecipeItemRepository.findAllByRecipeIds + ProductRecipeCostCalculator).
--
-- Este script:
--   1. Remove os vínculos antigos (errados) em product_recipe_item para os
--      15 produtos de produção própria das duas levas anteriores.
--   2. Cria 1 receita por produto (mesmo nome do produto), com os mesmos
--      itens/quantidades que estavam em product_recipe_item.
--   3. Liga cada produto à sua receita via product_recipe_link.
--
-- Os valores já gravados em product (cost_price, unit_cost_price,
-- price_per_kilogram, sale_price, profit_price) NÃO mudam — a fórmula de
-- custo é a mesma soma (quantidade × custo por unidade de consumo da
-- matéria-prima), só muda o caminho pelo qual o app soma isso.
--
-- Idempotente: pode rodar mais de uma vez sem duplicar (DELETE não gera erro
-- se já estiver vazio; INSERTs usam ON CONFLICT (id) DO NOTHING).

SET search_path TO bakers_bill;

-- =========================================================================
-- 1. Remove os vínculos antigos (produto -> matéria-prima direto)
-- =========================================================================

DELETE FROM product_recipe_item
WHERE product IN (
  'b0000000-0000-4000-8000-000000000001',
  'b0000000-0000-4000-8000-000000000002',
  'b0000000-0000-4000-8000-000000000003',
  'b0000000-0000-4000-8000-000000000004',
  'b0000000-0000-4000-8000-000000000005',
  'b0000000-0000-4000-8000-000000000006',
  'b0000000-0000-4000-8000-000000000007',
  'b0000000-0000-4000-8000-000000000008',
  'b0000000-0000-4000-8000-000000000009',
  'b0000000-0000-4000-8000-000000000010',
  'b0000000-0000-4000-8000-000000000011',
  'b0000000-0000-4000-8000-000000000012',
  'b0000000-0000-4000-8000-000000000013',
  'b0000000-0000-4000-8000-000000000014',
  'b0000000-0000-4000-8000-000000000015'
);

